/* Ispina Lokalnie 1.82.04 — bezpieczne poprawki audytowe.
   Nie zmienia logiki planera, rozkładów, powiadomień ani ekranu powitalnego. */
(function(){
  'use strict';
  try{
    var d=document, n=window.IspinaNative, VERSION=(window.IL_APP_VERSION||'1.82.93');
    function replaceVersion(root){
      if(!root)return;
      var w=d.createTreeWalker(root,NodeFilter.SHOW_TEXT,null,false),x;
      while(x=w.nextNode()){
        if(/1\.81\.11|1\.81\.14/.test(x.nodeValue))
          x.nodeValue=x.nodeValue.replace(/1\.81\.11|1\.81\.14/g,VERSION);
      }
    }
    function wasteData(){
      try{
        if(!n||!n.getWasteData)return null;
        var x=n.getWasteData('');
        return x?JSON.parse(x):null;
      }catch(e){return null}
    }
    function setWasteStatus(){
      var card=d.getElementById('ilWasteCard'),meta=d.getElementById('ilWasteMeta');
      if(!card||!meta)return;
      var x=wasteData(), online=navigator.onLine!==false;
      var stamp=x&&x.updatedAt?new Date(x.updatedAt):null;
      var info=online?'Dane aktualizują się automatycznie':'Brak internetu — pokazuję ostatnio zapisane dane';
      if(stamp&&!isNaN(stamp.getTime())){
        info+=' • sprawdzono '+stamp.toLocaleDateString('pl-PL')+' '+stamp.toLocaleTimeString('pl-PL',{hour:'2-digit',minute:'2-digit'});
      }
      meta.textContent=info;
    }
    function addWasteTools(){
      var card=d.getElementById('ilWasteCard');
      if(!card||d.getElementById('ilWasteAuditTools'))return;
      var s=d.createElement('style');
      s.textContent='#ilWasteAuditTools{display:flex;gap:7px;align-items:center;margin-top:8px;flex-wrap:wrap}#ilWasteAuditTools button{border:1px solid #c9ded8;border-radius:11px;padding:8px 10px;background:#f5faf8;color:#286158;font-weight:850;font-size:10px}#ilWasteAuditTools .auditHint{font-size:10px;color:#6d8078}#ilAuditScheduleNote{margin:8px 0;padding:9px 10px;border-radius:12px;background:#fffaf0;border:1px solid #eee0bd;color:#75613a;font-size:10px;line-height:1.35}';
      d.head.appendChild(s);
      var box=d.createElement('div');box.id='ilWasteAuditTools';
      box.innerHTML='<button type="button" id="ilWasteRefresh">Sprawdź teraz</button><span class="auditHint">Źródło: Gmina Drwinia</span>';
      card.appendChild(box);
      var b=d.getElementById('ilWasteRefresh');
      b.onclick=function(){
        if(b.disabled)return;
        b.disabled=true;b.textContent='Sprawdzam…';
        var r=d.getElementById('refreshall');if(r)r.click();
        setTimeout(function(){b.disabled=false;b.textContent='Sprawdź teraz';setWasteStatus()},9000);
      };
    }
    function addScheduleNote(){
      var v=d.getElementById('vdep')||d.getElementById('vplan');
      if(!v||d.getElementById('ilAuditScheduleNote'))return;
      var p=d.createElement('div');p.id='ilAuditScheduleNote';
      p.textContent='Uwaga: część czasów linii gminnej jest orientacyjna i została wyliczona między oficjalnie podanymi przystankami.';
      v.insertBefore(p,v.firstChild);
    }
    function init(){
      replaceVersion(d.body);addWasteTools();setWasteStatus();addScheduleNote();
      var v=d.getElementById('vset');
      if(v&&!d.getElementById('ilAuditNotifyStatus')&&n&&n.isWasteEnabled){
        var p=d.createElement('p');p.id='ilAuditNotifyStatus';p.className='hint';
        p.textContent=n.isWasteEnabled()?'✓ Powiadomienia o odpadach są włączone.':'Powiadomienia o odpadach są wyłączone.';
        v.appendChild(p);
      }
    }
    init();
    setTimeout(init,700);setTimeout(init,2200);
    setInterval(function(){setWasteStatus();if(navigator.onLine!==false)replaceVersion(d.body)},30000);
    addEventListener('online',setWasteStatus);addEventListener('offline',setWasteStatus);
  }catch(e){console.warn('Audit UI patch:',e)}
})();
