      list.innerHTML=out.map(function(x){var ds=cap(x.date.toLocaleDateString('pl-PL',{weekday:'long',day:'numeric',month:'long'})),ts=x.types.map(function(t){return map[t]||t}).join(' • ');return'<div class="sr-waste-row"><div class="sr-waste-date">'+esc(ds)+'</div><div class="sr-waste-type">'+esc(ts)+'</div></div>'}).join('');
