  addEventListener('click',function(e){var b=e.target&&e.target.closest?e.target.closest('#nav .nb'):null;if(!b)return;var u=b.getAttribute('data-u')||'';if(u===WP||u===WP+'/'){e.preventDefault();e.stopImmediatePropagation();dashboard()}},true);
  // Make the current migration state visible in Settings/diagnostics without adding clutter.
