    var rows=c.querySelectorAll('.ilnm-row');
    if(rows&&rows.length){
     var found=false;Array.prototype.forEach.call(rows,function(r){if((r.textContent||'').indexOf('Strony informacyjne')>=0)found=true});
     if(!found){var r=d.createElement('div');r.className='ilnm-row';r.innerHTML='<span>Strony informacyjne</span><b>Lokalne widoki + router linków</b>';var note=c.querySelector('.ilnm-note');if(note)c.insertBefore(r,note);else c.appendChild(r)}
    }
