;/* Ispina Lokalnie 1.82.95 — NATIVE RADIO BACKGROUND + MEDIA NOTIFICATION */
(function(){
 'use strict';
 try{
  var d=document,VER=window.IL_BUILD.versionName,VC=window.IL_BUILD.versionCode;
  window.IL_APP_VERSION=VER;window.IL_APP_VERSION_CODE=VC;
  var ST={
   pr1:{name:'Polskie Radio Program 1',url:'https://stream11.polskieradio.pl/pr1/pr1.sdp/playlist.m3u8',btn:'rtvPr1',retry:'rtvPr1Retry',status:'rtvStatusPr1'},
   eska:{name:'Radio ESKA Bochnia',url:'https://ic1.smcdn.pl/2330-1.mp3',btn:'rtvEska',retry:'rtvEskaRetry',status:'rtvStatusEska'},
   rmf:{name:'RMF FM',url:'https://rs101-krk.rmfstream.pl/rmf_fm',btn:'rtvRmf',retry:'rtvRmfRetry',status:'rtvStatusRmf'}
  };
  var current='';
  try{current=localStorage.getItem('il_native_radio_station_18295')||''}catch(_e){}
  var playing=false;
  try{playing=localStorage.getItem('il_native_radio_playing_18295')==='1'}catch(_e){}

  function el(id){return d.getElementById(id)}
  function send(cmd,key){
   var s=key&&ST[key]?ST[key]:null;
   var uri='ilradio://'+cmd;
   if(s&&cmd==='play') uri+='?name='+encodeURIComponent(s.name)+'&url='+encodeURIComponent(s.url);
   var ok=false;
   try{if(window.IL_OPEN_EXTERNAL_1862)ok=!!window.IL_OPEN_EXTERNAL_1862(uri)}catch(_e){}
   if(!ok){try{location.href=uri}catch(_e){}}
  }
  function killLegacyAudio(){
   try{
    var a=el('ilBackgroundRadio');
    if(a){a.pause();a.removeAttribute('src');a.load()}
    if('mediaSession' in navigator){
     try{navigator.mediaSession.setActionHandler('play',null)}catch(_e){}
     try{navigator.mediaSession.setActionHandler('pause',null)}catch(_e){}
     try{navigator.mediaSession.setActionHandler('stop',null)}catch(_e){}
     try{navigator.mediaSession.playbackState='none'}catch(_e){}
    }
   }catch(_e){}
  }
  function status(key,text,kind){
   var x=ST[key]&&el(ST[key].status);if(!x)return;
   x.textContent=text||'';
   try{x.classList.toggle('error',kind==='error')}catch(_e){}
  }
  function syncUi(){
   Object.keys(ST).forEach(function(k){
    var b=el(ST[k].btn);if(b)b.textContent=(playing&&current===k)?'⏸ Pauza':'▶ Słuchaj';
    var r=el(ST[k].retry);if(r)r.hidden=true;
    status(k,(playing&&current===k)?'Odtwarzanie w tle • sterowanie w powiadomieniu':'Gotowe do odtwarzania');
   });
   var now=el('rtvNow'),nm=el('rtvNowName'),tg=el('rtvNowToggle');
   if(now){if(current)now.classList.add('on');else now.classList.remove('on')}
   if(nm&&current&&ST[current])nm.textContent=ST[current].name;
   if(tg)tg.textContent=playing?'⏸ Pauza':'▶ Wznów';
   var v=el('ilDiagVersion');if(v)v.textContent=VER;
   var vl=el('ilVersionLabel');if(vl)vl.textContent=VER;
  }
  function remember(){
   try{localStorage.setItem('il_native_radio_station_18295',current||'');localStorage.setItem('il_native_radio_playing_18295',playing?'1':'0')}catch(_e){}
  }
  function play(key){
   if(!ST[key])return;
   killLegacyAudio();
   if(current===key&&playing){playing=false;send('toggle');remember();syncUi();return}
   current=key;playing=true;send('play',key);remember();syncUi();
  }
  function toggle(){
   if(!current||!ST[current])return;
   killLegacyAudio();playing=!playing;send('toggle');remember();syncUi();
  }
  function stop(){
   killLegacyAudio();send('stop');playing=false;current='';remember();syncUi();
  }
  function capture(id,fn){
   var x=el(id);if(!x||x.dataset.ilNativeRadio18295==='1')return;
   x.dataset.ilNativeRadio18295='1';
   x.addEventListener('click',function(e){try{e.preventDefault();e.stopImmediatePropagation()}catch(_e){}fn()},true);
  }
  function bind(){
   capture('rtvPr1',function(){play('pr1')});
   capture('rtvEska',function(){play('eska')});
   capture('rtvRmf',function(){play('rmf')});
   capture('rtvPr1Retry',function(){play('pr1')});
   capture('rtvEskaRetry',function(){play('eska')});
   capture('rtvRmfRetry',function(){play('rmf')});
   capture('rtvNowToggle',toggle);
   capture('rtvStop',stop);
   syncUi();
  }
  bind();setTimeout(bind,250);setTimeout(bind,1200);
  d.addEventListener('visibilitychange',function(){if(!d.hidden)setTimeout(syncUi,120)});
 }catch(e){try{console.warn('NATIVE RADIO 1.82.95:',e)}catch(_e){}}
})();

